\", \"8.96\"],\n    [\"Gemma-2B\", \"ETO\", \"0%\", \"91.67\", \"83.87\", \"78.26\", \"52.38\", \"77.78\", \"29.41\", \"71.64\"],\n    [\"Gemma-2B\", \"KnowAgent\", \"100%\", \"91.67\", \"90.32\", \"69.57\", \"71.43\", \"66.67\", \"41.18\", \"73.88\"],\n    [\"Gemma-2B\", \"WKM\", \"100%\", \"91.67\", \"87.10\", \"78.26\", \"71.43\", \"61.11\", \"52.94\", \"76.12\"],\n    [\"Gemma-2B\", \"KnowSelf\", \"26.41%\", \"87.50\", \"93.55\", \"73.91\", \"76.19\", \"83.33\", \"52.94\", \"79.85\"],\n  ];\n\n  const highlightRows = [9, 14]; // KnowSelf rows (0-indexed in data)\n  const tableData = [headers];\n  rows.forEach((row, ri) => {\n    const isHL = highlightRows.includes(ri);\n    tableData.push(row.map(cell => ({\n      text: cell,\n      options: isHL ? { ...hlOpts } : { ...cellOpts, fill: { color: ri % 2 === 0 ? C.white : C.cardBg } },\n    })));\n  });\n\n  s.addTable(tableData, {\n    x: 0.25, y: 0.85, w: 9.5,\n    colW: [0.85, 0.95, 0.7, 0.8, 0.8, 0.8, 0.8, 0.85, 0.85, 0.7],\n    border: { pt: 0.5, color: C.lightGray },\n    rowH: [0.28, ...Array(15).fill(0.27)],\n    margin: [1, 2, 1, 2],\n  });\n\n  s.addText(\"Success rates (%) on six ALFWorld task types. Highlighted: KnowSelf rows.\", {\n    x: 0.4, y: 5.15, w: 9.2, h: 0.3,\n    fontSize: 10, fontFace: FONT_B, color: C.midGray, italic: true, align: \"left\", margin: 0,\n  });\n}\n\n// ========== SLIDE 7: EFFICIENCY — CHART ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"Minimal Knowledge, Maximum Impact\", {\n    x: 0.6, y: 0.3, w: 8.8, h: 0.55,\n    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"KnowSelf uses 15–26% knowledge queries vs. 100% for competing methods, yet achieves best overall scores\", {\n    x: 0.6, y: 0.85, w: 8.8, h: 0.35,\n    fontSize: 13, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  // Bar chart: Accuracy comparison\n  const labels = [\"ExpeL\\n(GPT-4o)\", \"KnowAgent\\n(Llama-8B)\", \"WKM\\n(Llama-8B)\", \"KnowSelf\\n(Llama-8B)\", \"KnowAgent\\n(Gemma-2B)\", \"WKM\\n(Gemma-2B)\", \"KnowSelf\\n(Gemma-2B)\"];\n  const accuracyVals = [79.85, 75.37, 77.61, 84.33, 73.88, 76.12, 79.85];\n  const knowPctVals = [100, 100, 100, 15.01, 100, 100, 26.41];\n\n  s.addChart(pres.charts.BAR, [\n    { name: \"Overall Accuracy (%)\", labels, values: accuracyVals },\n    { name: \"Knowledge Usage (%)\", labels, values: knowPctVals },\n  ], {\n    x: 0.5, y: 1.35, w: 9.0, h: 3.5,\n    barDir: \"col\",\n    barGrouping: \"clustered\",\n    chartColors: [C.teal, C.accent],\n    chartArea: { fill: { color: C.white }, roundedCorners: true },\n    catAxisLabelColor: C.bodyText,\n    catAxisLabelFontSize: 8,\n    valAxisLabelColor: C.midGray,\n    valGridLine: { color: C.lightGray, size: 0.5 },\n    catGridLine: { style: \"none\" },\n    showValue: true,\n    dataLabelPosition: \"outEnd\",\n    dataLabelColor: C.darkText,\n    dataLabelFontSize: 8,\n    showLegend: true,\n    legendPos: \"b\",\n    legendFontSize: 10,\n  });\n\n  // Callout\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 5.0, w: 9.0, h: 0.45, fill: { color: C.navy } });\n  s.addText(\"KnowSelf (Llama-8B): 84.33% accuracy with only 15% knowledge — surpasses GPT-4o ExpeL at 79.85% with 100% knowledge\", {\n    x: 0.7, y: 5.0, w: 8.6, h: 0.45,\n    fontSize: 11, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n}\n\n// ========== SLIDE 8: KEY TAKEAWAYS ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.darkBg };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"Key Takeaways & Future Directions\", {\n    x: 0.6, y: 0.3, w: 8.8, h: 0.6,\n    fontSize: 30, fontFace: FONT_H, color: C.white, bold: true, align: \"left\", margin: 0,\n  });\n\n  const takeaways = [\n    { num: \"1\", text: \"Indiscriminate knowledge injection is wasteful and suboptimal — selective use consistently outperforms blanket application\" },\n    { num: \"2\", text: \"Agents can learn situational self-awareness via special tokens with lightweight heuristic labeling — no expensive annotation needed\" },\n    { num: \"3\", text: \"KnowSelf (Llama-8B) achieves 84.33%, surpassing GPT-4o ReAct (76.12%) and GPT-4o ExpeL (79.85%)\" },\n    { num: \"4\", text: \"Only 15–26% knowledge usage needed versus 100% for KnowAgent, WKM, and ExpeL\" },\n    { num: \"5\", text: \"Scales across model sizes — even Gemma-2B reaches 79.85%, matching GPT-4o ExpeL\" },\n  ];\n\n  takeaways.forEach((t, i) => {\n    const yBase = 1.15 + i * 0.72;\n    s.addText(t.num, {\n      x: 0.6, y: yBase, w: 0.45, h: 0.45,\n      fontSize: 15, fontFace: FONT_B, color: C.darkBg, bold: true, align: \"center\", valign: \"middle\",\n      shape: pres.shapes.OVAL, fill: { color: C.tealLight },\n    });\n    s.addText(t.text, {\n      x: 1.25, y: yBase, w: 8.2, h: 0.55,\n      fontSize: 13, fontFace: FONT_B, color: C.lightGray, align: \"left\", valign: \"middle\", margin: 0,\n    });\n  });\n\n  // Future directions\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.55, w: 8.8, h: 0.06, fill: { color: C.teal, transparency: 50 } });\n  s.addText(\"Future Directions\", {\n    x: 0.6, y: 4.7, w: 8.8, h: 0.35,\n    fontSize: 16, fontFace: FONT_H, color: C.tealLight, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Extend to multi-modal agents and real-world robotics  •  Explore dynamic knowledge base construction  •  Apply self-awareness paradigm to multi-agent collaboration\", {\n    x: 0.6, y: 5.05, w: 8.8, h: 0.4,\n    fontSize: 11, fontFace: FONT_B, color: C.midGray, align: \"left\", margin: 0,\n  });\n}\n\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" }).then(() => {\n  console.log(\"Presentation saved to /app/output/final_deck.pptx\");\n}).catch(err => {\n  console.error(\"Error:\", err);\n});\n", "numLines": 537, "startLine": 1, "totalLines": 537}}

