const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "KnowSelf Research";
pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";

// Color palette — Midnight Executive with teal accents for ML/AI feel
const C = {
  darkBg: "0F1B2D",
  navy: "1A2744",
  teal: "0891B2",
  tealLight: "22D3EE",
  white: "FFFFFF",
  offWhite: "F0F4F8",
  lightGray: "E2E8F0",
  midGray: "94A3B8",
  darkText: "1E293B",
  bodyText: "334155",
  accent: "F59E0B",
  green: "10B981",
  red: "EF4444",
  cardBg: "F8FAFC",
};

const FONT_H = "Georgia";
const FONT_B = "Calibri";

// Helper: fresh shadow
const cardShadow = () => ({ type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.10 });

// ========== SLIDE 1: TITLE ==========
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  // Decorative teal bar top
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  // Title
  s.addText("KnowSelf", {
    x: 0.8, y: 1.0, w: 8.4, h: 1.0,
    fontSize: 48, fontFace: FONT_H, color: C.tealLight, bold: true, align: "left", margin: 0,
  });
  s.addText("Agentic Knowledgeable Self-Awareness\nfor LLM-Based Agents", {
    x: 0.8, y: 2.0, w: 8.4, h: 1.1,
    fontSize: 22, fontFace: FONT_H, color: C.white, align: "left", margin: 0,
  });
  // Tagline
  s.addText("Teaching agents to autonomously decide when to act, reflect, or seek knowledge", {
    x: 0.8, y: 3.3, w: 8.4, h: 0.5,
    fontSize: 14, fontFace: FONT_B, color: C.midGray, italic: true, align: "left", margin: 0,
  });
  // Source
  s.addText("arxiv.org/abs/2504.03553", {
    x: 0.8, y: 4.8, w: 4, h: 0.4,
    fontSize: 11, fontFace: FONT_B, color: C.teal, align: "left", margin: 0,
  });
  // Decorative shapes
  s.addShape(pres.shapes.RECTANGLE, { x: 8.8, y: 1.0, w: 0.08, h: 2.5, fill: { color: C.teal, transparency: 40 } });
}

// ========== SLIDE 2: PROBLEM ==========
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("The Problem: Indiscriminate \"Flood Irrigation\"", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.6,
    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: "left", margin: 0,
  });

  // Three paradigm cards
  const paradigms = [
    { title: "Trajectory Imitation", desc: "ReAct: blindly imitates gold trajectories without understanding when help is needed", icon: "1" },
    { title: "Trial-and-Error", desc: "Reflexion: always reflects even when the agent already knows the correct action", icon: "2" },
    { title: "Knowledge-Augmented", desc: "KnowAgent, WKM: injects domain knowledge at every step — 100% usage regardless of need", icon: "3" },
  ];

  paradigms.forEach((p, i) => {
    const yBase = 1.15 + i * 1.15;
    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yBase, w: 5.4, h: 0.95, fill: { color: C.white }, shadow: cardShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yBase, w: 0.07, h: 0.95, fill: { color: C.red } });
    s.addText(p.icon, {
      x: 0.85, y: yBase + 0.08, w: 0.4, h: 0.4,
      fontSize: 14, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle",
      shape: pres.shapes.OVAL, fill: { color: C.red },
    });
    s.addText(p.title, {
      x: 1.4, y: yBase + 0.08, w: 4.4, h: 0.32,
      fontSize: 14, fontFace: FONT_B, color: C.darkText, bold: true, align: "left", margin: 0,
    });
    s.addText(p.desc, {
      x: 1.4, y: yBase + 0.42, w: 4.4, h: 0.45,
      fontSize: 11, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
    });
  });

  // Right side: contrast callout
  s.addShape(pres.shapes.RECTANGLE, { x: 6.3, y: 1.15, w: 3.3, h: 3.45, fill: { color: C.navy }, shadow: cardShadow() });
  s.addText("Human Approach", {
    x: 6.5, y: 1.35, w: 2.9, h: 0.4,
    fontSize: 16, fontFace: FONT_H, color: C.tealLight, bold: true, align: "left", margin: 0,
  });
  s.addText("Humans possess situational self-awareness: the metacognitive ability to assess whether they can handle a situation directly, need to pause and reflect, or must seek external help.", {
    x: 6.5, y: 1.85, w: 2.9, h: 1.4,
    fontSize: 11.5, fontFace: FONT_B, color: C.lightGray, align: "left", margin: 0,
  });
  s.addText("KnowSelf brings this\ncapability to LLM agents.", {
    x: 6.5, y: 3.5, w: 2.9, h: 0.7,
    fontSize: 13, fontFace: FONT_B, color: C.accent, bold: true, align: "left", margin: 0,
  });

  // Bottom note
  s.addText("Result: fragile planning, pattern collapse, and unnecessarily high inference costs", {
    x: 0.6, y: 4.85, w: 8.8, h: 0.35,
    fontSize: 11, fontFace: FONT_B, color: C.midGray, italic: true, align: "left", margin: 0,
  });
}

// ========== SLIDE 3: THREE THINKING MODES — Decision Tree ==========
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("Three Situational Thinking Modes", {
    x: 0.6, y: 0.3, w: 8.8, h: 0.6,
    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: "left", margin: 0,
  });

  // Decision tree layout — top diamond, branching to three boxes
  // Decision node 1
  const dY = 1.2;
  s.addShape(pres.shapes.RECTANGLE, { x: 3.0, y: dY, w: 4.0, h: 0.65, fill: { color: C.navy }, shadow: cardShadow() });
  s.addText("Agent Predicts Action at Step t", {
    x: 3.0, y: dY, w: 4.0, h: 0.65,
    fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });

  // Decision node 2
  const d2Y = 2.15;
  s.addShape(pres.shapes.RECTANGLE, { x: 3.0, y: d2Y, w: 4.0, h: 0.55, fill: { color: C.teal } });
  s.addText("Does predicted action match gold action?", {
    x: 3.0, y: d2Y, w: 4.0, h: 0.55,
    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });

  // Arrow down from node 1 to node 2
  s.addShape(pres.shapes.LINE, { x: 5.0, y: dY + 0.65, w: 0, h: 0.3, line: { color: C.midGray, width: 1.5 } });

  // YES branch — Fast Thinking (left)
  s.addText("YES", {
    x: 1.3, y: d2Y + 0.05, w: 0.6, h: 0.4,
    fontSize: 10, fontFace: FONT_B, color: C.green, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 1.9, y: d2Y + 0.28, w: 1.1, h: 0, line: { color: C.green, width: 1.5 } });

  const fastY = 3.1;
  s.addShape(pres.shapes.RECTANGLE, { x: 0.4, y: fastY, w: 2.7, h: 1.8, fill: { color: C.white }, shadow: cardShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.4, y: fastY, w: 2.7, h: 0.45, fill: { color: C.green } });
  s.addText("Fast Thinking", {
    x: 0.4, y: fastY, w: 2.7, h: 0.45,
    fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });
  s.addText("Agent directly produces the correct action with minimal deliberation.\n\nNo reflection or knowledge needed.", {
    x: 0.6, y: fastY + 0.55, w: 2.3, h: 1.15,
    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });
  // Arrow from decision to fast
  s.addShape(pres.shapes.LINE, { x: 1.75, y: d2Y + 0.55, w: 0, h: 0.4, line: { color: C.green, width: 1.5 } });

  // NO branch — goes to reflection check (center-right)
  s.addText("NO", {
    x: 7.2, y: d2Y + 0.05, w: 0.5, h: 0.4,
    fontSize: 10, fontFace: FONT_B, color: C.red, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 7.0, y: d2Y + 0.28, w: 0.2, h: 0, line: { color: C.red, width: 1.5 } });

  // Reflection check node
  const r2Y = d2Y + 0.85;
  s.addShape(pres.shapes.RECTANGLE, { x: 5.6, y: r2Y, w: 3.2, h: 0.5, fill: { color: C.accent } });
  s.addText("Can reflection fix it?", {
    x: 5.6, y: r2Y, w: 3.2, h: 0.5,
    fontSize: 12, fontFace: FONT_B, color: C.darkText, bold: true, align: "center", valign: "middle", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 7.2, y: d2Y + 0.55, w: 0, h: 0.3, line: { color: C.red, width: 1.5 } });

  // Slow Thinking (center)
  const slowY = 3.8;
  s.addShape(pres.shapes.RECTANGLE, { x: 3.5, y: slowY, w: 2.7, h: 1.1, fill: { color: C.white }, shadow: cardShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 3.5, y: slowY, w: 2.7, h: 0.4, fill: { color: C.accent } });
  s.addText("Slow Thinking", {
    x: 3.5, y: slowY, w: 2.7, h: 0.4,
    fontSize: 13, fontFace: FONT_B, color: C.darkText, bold: true, align: "center", valign: "middle", margin: 0,
  });
  s.addText("Agent self-corrects through reflection after initial error.", {
    x: 3.7, y: slowY + 0.48, w: 2.3, h: 0.55,
    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });
  // YES arrow from reflection check to slow
  s.addText("YES", {
    x: 5.0, y: r2Y + 0.05, w: 0.5, h: 0.4,
    fontSize: 10, fontFace: FONT_B, color: C.accent, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 5.6, y: r2Y + 0.25, w: 0, h: 0, line: { color: C.accent, width: 1.5 } });
