[metadata] {"type": "text", "file": {"filePath": "/app/build_deck.js", "content": "const pptxgen = require(\"pptxgenjs\");\n\nconst pres = new pptxgen();\npres.layout = \"LAYOUT_16x9\";\npres.author = \"KnowSelf Research\";\npres.title = \"KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge\";\n\nconst C = {\n  darkBg: \"0F1B2D\",\n  navy: \"1A2744\",\n  teal: \"0891B2\",\n  tealLight: \"22D3EE\",\n  white: \"FFFFFF\",\n  offWhite: \"F0F4F8\",\n  lightGray: \"E2E8F0\",\n  midGray: \"64748B\",\n  darkText: \"1E293B\",\n  bodyText: \"334155\",\n  accent: \"F59E0B\",\n  green: \"10B981\",\n  red: \"EF4444\",\n  cardBg: \"F8FAFC\",\n};\n\nconst FONT_H = \"Georgia\";\nconst FONT_B = \"Calibri\";\nconst cardShadow = () => ({ type: \"outer\", blur: 4, offset: 1, angle: 135, color: \"000000\", opacity: 0.10 });\n\n// ========== SLIDE 1: TITLE ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.darkBg };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"KnowSelf\", {\n    x: 0.8, y: 1.2, w: 8.0, h: 0.9,\n    fontSize: 48, fontFace: FONT_H, color: C.tealLight, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Agentic Knowledgeable Self-Awareness\\nfor LLM-Based Agents\", {\n    x: 0.8, y: 2.1, w: 8.0, h: 1.0,\n    fontSize: 22, fontFace: FONT_H, color: C.white, align: \"left\", margin: 0,\n  });\n  s.addText(\"Teaching agents to autonomously decide when to act, reflect, or seek knowledge\", {\n    x: 0.8, y: 3.3, w: 8.0, h: 0.5,\n    fontSize: 14, fontFace: FONT_B, color: C.lightGray, italic: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"arxiv.org/abs/2504.03553\", {\n    x: 0.8, y: 4.2, w: 4, h: 0.4,\n    fontSize: 12, fontFace: FONT_B, color: C.teal, align: \"left\", margin: 0,\n  });\n  s.addShape(pres.shapes.RECTANGLE, { x: 8.8, y: 1.2, w: 0.08, h: 2.5, fill: { color: C.teal, transparency: 40 } });\n}\n\n// ========== SLIDE 2: PROBLEM ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"The Problem: Indiscriminate \\\"Flood Irrigation\\\"\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.55,\n    fontSize: 26, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n\n  const paradigms = [\n    { title: \"Trajectory Imitation\", desc: \"ReAct: blindly imitates gold trajectories without understanding when help is needed\", icon: \"1\" },\n    { title: \"Trial-and-Error\", desc: \"Reflexion: always reflects even when the agent already knows the correct action\", icon: \"2\" },\n    { title: \"Knowledge-Augmented\", desc: \"KnowAgent, WKM: injects domain knowledge at every step — 100% usage regardless of need\", icon: \"3\" },\n  ];\n\n  paradigms.forEach((p, i) => {\n    const yBase = 1.1 + i * 1.05;\n    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yBase, w: 5.2, h: 0.85, fill: { color: C.white }, shadow: cardShadow() });\n    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yBase, w: 0.07, h: 0.85, fill: { color: C.red } });\n    s.addText(p.icon, {\n      x: 0.85, y: yBase + 0.08, w: 0.35, h: 0.35,\n      fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\",\n      shape: pres.shapes.OVAL, fill: { color: C.red },\n    });\n    s.addText(p.title, {\n      x: 1.35, y: yBase + 0.06, w: 4.3, h: 0.3,\n      fontSize: 13, fontFace: FONT_B, color: C.darkText, bold: true, align: \"left\", margin: 0,\n    });\n    s.addText(p.desc, {\n      x: 1.35, y: yBase + 0.38, w: 4.3, h: 0.4,\n      fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n    });\n  });\n\n  // Right callout — within margin\n  s.addShape(pres.shapes.RECTANGLE, { x: 6.1, y: 1.1, w: 3.3, h: 3.15, fill: { color: C.navy }, shadow: cardShadow() });\n  s.addText(\"Human Approach\", {\n    x: 6.3, y: 1.3, w: 2.9, h: 0.35,\n    fontSize: 15, fontFace: FONT_H, color: C.tealLight, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Humans possess situational self-awareness: the metacognitive ability to assess whether they can handle a situation directly, need to pause and reflect, or must seek external help.\", {\n    x: 6.3, y: 1.75, w: 2.9, h: 1.3,\n    fontSize: 11, fontFace: FONT_B, color: C.lightGray, align: \"left\", margin: 0,\n  });\n  s.addText(\"KnowSelf brings this\\ncapability to LLM agents.\", {\n    x: 6.3, y: 3.2, w: 2.9, h: 0.7,\n    fontSize: 13, fontFace: FONT_B, color: C.accent, bold: true, align: \"left\", margin: 0,\n  });\n\n  s.addText(\"Result: fragile planning, pattern collapse, and unnecessarily high inference costs\", {\n    x: 0.6, y: 4.65, w: 8.8, h: 0.35,\n    fontSize: 11, fontFace: FONT_B, color: C.midGray, italic: true, align: \"left\", margin: 0,\n  });\n}\n\n// ========== SLIDE 3: THREE THINKING MODES ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"Three Situational Thinking Modes\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.55,\n    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n\n  // Node 1\n  const dY = 1.1;\n  s.addShape(pres.shapes.RECTANGLE, { x: 3.2, y: dY, w: 3.6, h: 0.55, fill: { color: C.navy }, shadow: cardShadow() });\n  s.addText(\"Agent Predicts Action at Step t\", {\n    x: 3.2, y: dY, w: 3.6, h: 0.55,\n    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n\n  // Arrow down\n  s.addShape(pres.shapes.LINE, { x: 5.0, y: dY + 0.55, w: 0, h: 0.25, line: { color: C.midGray, width: 1.5 } });\n\n  // Decision node\n  const d2Y = 1.9;\n  s.addShape(pres.shapes.RECTANGLE, { x: 3.2, y: d2Y, w: 3.6, h: 0.5, fill: { color: C.teal } });\n  s.addText(\"Does predicted action match gold action?\", {\n    x: 3.2, y: d2Y, w: 3.6, h: 0.5,\n    fontSize: 11, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n\n  // YES branch left → Fast Thinking\n  s.addShape(pres.shapes.LINE, { x: 2.0, y: d2Y + 0.25, w: 1.2, h: 0, line: { color: C.green, width: 1.5 } });\n  s.addText(\"YES\", {\n    x: 2.2, y: d2Y - 0.18, w: 0.6, h: 0.25,\n    fontSize: 9, fontFace: FONT_B, color: C.green, bold: true, align: \"center\", margin: 0,\n  });\n  s.addShape(pres.shapes.LINE, { x: 2.0, y: d2Y + 0.25, w: 0, h: 0.55, line: { color: C.green, width: 1.5 } });\n\n  const fastY = 2.7;\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: fastY, w: 2.8, h: 1.7, fill: { color: C.white }, shadow: cardShadow() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: fastY, w: 2.8, h: 0.4, fill: { color: C.green } });\n  s.addText(\"Fast Thinking\", {\n    x: 0.5, y: fastY, w: 2.8, h: 0.4,\n    fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n  s.addText(\"Agent directly produces the correct action with minimal deliberation.\\n\\nNo reflection or knowledge needed.\", {\n    x: 0.7, y: fastY + 0.5, w: 2.4, h: 1.1,\n    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  // NO branch right → Reflection check\n  s.addShape(pres.shapes.LINE, { x: 6.8, y: d2Y + 0.25, w: 0.7, h: 0, line: { color: C.red, width: 1.5 } });\n  s.addText(\"NO\", {\n    x: 7.0, y: d2Y - 0.18, w: 0.5, h: 0.25,\n    fontSize: 9, fontFace: FONT_B, color: C.red, bold: true, align: \"center\", margin: 0,\n  });\n  s.addShape(pres.shapes.LINE, { x: 7.5, y: d2Y + 0.25, w: 0, h: 0.35, line: { color: C.red, width: 1.5 } });\n\n  // Reflection check\n  const r2Y = 2.6;\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.9, y: r2Y, w: 3.2, h: 0.45, fill: { color: C.accent } });\n  s.addText(\"Can reflection fix it?\", {\n    x: 5.9, y: r2Y, w: 3.2, h: 0.45,\n    fontSize: 11, fontFace: FONT_B, color: C.darkText, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n\n  // YES → Slow Thinking\n  s.addShape(pres.shapes.LINE, { x: 5.9, y: r2Y + 0.22, w: 0, h: 0, line: { color: C.accent, width: 1.5 } });\n  s.addText(\"YES\", {\n    x: 4.6, y: r2Y + 0.02, w: 0.5, h: 0.25,\n    fontSize: 9, fontFace: FONT_B, color: C.accent, bold: true, align: \"center\", margin: 0,\n  });\n  s.addShape(pres.shapes.LINE, { x: 5.15, y: r2Y + 0.45, w: 0, h: 0.45, line: { color: C.accent, width: 1.5 } });\n\n  const slowY = 3.5;\n  s.addShape(pres.shapes.RECTANGLE, { x: 3.65, y: slowY, w: 2.8, h: 1.1, fill: { color: C.white }, shadow: cardShadow() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 3.65, y: slowY, w: 2.8, h: 0.38, fill: { color: C.accent } });\n  s.addText(\"Slow Thinking\", {\n    x: 3.65, y: slowY, w: 2.8, h: 0.38,\n    fontSize: 12, fontFace: FONT_B, color: C.darkText, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n  s.addText(\"Agent self-corrects through reflection after initial error.\", {\n    x: 3.85, y: slowY + 0.45, w: 2.4, h: 0.55,\n    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  // NO → Knowledgeable Thinking\n  s.addText(\"NO\", {\n    x: 9.0, y: r2Y + 0.02, w: 0.5, h: 0.25,\n    fontSize: 9, fontFace: FONT_B, color: C.red, bold: true, align: \"center\", margin: 0,\n  });\n  s.addShape(pres.shapes.LINE, { x: 8.25, y: r2Y + 0.45, w: 0, h: 0.6, line: { color: C.red, width: 1.5 } });\n\n  const knowY = 3.5;\n  s.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: knowY, w: 2.8, h: 1.1, fill: { color: C.white }, shadow: cardShadow() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: knowY, w: 2.8, h: 0.38, fill: { color: C.teal } });\n  s.addText(\"Knowledgeable Thinking\", {\n    x: 6.7, y: knowY, w: 2.8, h: 0.38,\n    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n  s.addText(\"Agent must consult external knowledge base.\", {\n    x: 6.9, y: knowY + 0.45, w: 2.4, h: 0.55,\n    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n}\n\n// ========== SLIDE 4: FRAMEWORK PIPELINE ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"KnowSelf Framework Pipeline\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.55,\n    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n\n  const steps = [\n    { num: \"1\", title: \"Data Construction\", lines: [\"Agent self-explores environments\", \"Heuristic criterion classifies each step\", \"Special tokens inserted for situation type\"] },\n    { num: \"2\", title: \"Two-Stage Training\", lines: [\"Stage A: Supervised Fine-Tuning (SFT)\", \"Stage B: Reward-based Policy Optimization (RPO)\", \"Refines special token generation\"] },\n    { num: \"3\", title: \"Self-Aware Inference\", lines: [\"Agent generates special tokens at each step\", \"Tokens trigger: action / reflection / retrieval\", \"Knowledge retrieved only when needed\"] },\n  ];\n\n  steps.forEach((st, i) => {\n    const xBase = 0.6 + i * 3.05;\n    s.addShape(pres.shapes.RECTANGLE, { x: xBase, y: 1.1, w: 2.8, h: 3.2, fill: { color: C.white }, shadow: cardShadow() });\n    s.addText(st.num, {\n      x: xBase + 1.0, y: 1.3, w: 0.6, h: 0.6,\n      fontSize: 20, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\",\n      shape: pres.shapes.OVAL, fill: { color: C.teal },\n    });\n    s.addText(st.title, {\n      x: xBase + 0.2, y: 2.05, w: 2.4, h: 0.4,\n      fontSize: 14, fontFace: FONT_B, color: C.darkText, bold: true, align: \"center\", margin: 0,\n    });\n    const bulletItems = st.lines.map((l, li) => ({\n      text: l,\n      options: { bullet: true, breakLine: li < st.lines.length - 1, fontSize: 11, fontFace: FONT_B, color: C.bodyText },\n    }));\n    s.addText(bulletItems, { x: xBase + 0.25, y: 2.55, w: 2.3, h: 1.5, margin: 0, paraSpaceAfter: 6 });\n\n    if (i < 2) {\n      s.addShape(pres.shapes.LINE, { x: xBase + 2.8, y: 2.7, w: 0.25, h: 0, line: { color: C.teal, width: 2 } });\n    }\n  });\n\n  s.addText(\"Lightweight and data-efficient: heuristic labeling on self-explored trajectories — no expensive human annotation\", {\n    x: 0.6, y: 4.6, w: 8.8, h: 0.35,\n    fontSize: 11, fontFace: FONT_B, color: C.midGray, italic: true, align: \"left\", margin: 0,\n  });\n}\n\n// ========== SLIDE 5: QUALITATIVE EXAMPLES ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"KnowSelf vs. Strong Baselines: Qualitative Examples\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.5,\n    fontSize: 26, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n\n  // Example A\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.05, w: 4.3, h: 3.4, fill: { color: C.white }, shadow: cardShadow() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.05, w: 4.3, h: 0.42, fill: { color: C.navy } });\n  s.addText(\"Task: \\\"Put a hot mug in cabinet\\\"\", {\n    x: 0.7, y: 1.05, w: 3.9, h: 0.42,\n    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: \"left\", valign: \"middle\", margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 1.65, w: 3.9, h: 1.05, fill: { color: \"FEF2F2\" } });\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 1.65, w: 0.06, h: 1.05, fill: { color: C.red } });\n  s.addText(\"OpenAI-O1\", {\n    x: 0.95, y: 1.7, w: 3.4, h: 0.25,\n    fontSize: 11, fontFace: FONT_B, color: C.red, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Incorrectly tries to take an egg from the microwave after opening it. Fails to identify the mug heating step.\", {\n    x: 0.95, y: 1.97, w: 3.4, h: 0.65,\n    fontSize: 10, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 2.95, w: 3.9, h: 1.05, fill: { color: \"F0FDF4\" } });\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 2.95, w: 0.06, h: 1.05, fill: { color: C.green } });\n  s.addText(\"KnowSelf (Llama-8B)\", {\n    x: 0.95, y: 3.0, w: 3.4, h: 0.25,\n    fontSize: 11, fontFace: FONT_B, color: C.green, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Uses Reflection token to realize it should heat the mug using the open microwave. Correct action follows.\", {\n    x: 0.95, y: 3.27, w: 3.4, h: 0.65,\n    fontSize: 10, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  // Example B\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.05, w: 4.3, h: 3.4, fill: { color: C.white }, shadow: cardShadow() });\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 1.05, w: 4.3, h: 0.42, fill: { color: C.navy } });\n  s.addText(\"Task: \\\"Put a saltshaker in drawer\\\"\", {\n    x: 5.4, y: 1.05, w: 3.9, h: 0.42,\n    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: \"left\", valign: \"middle\", margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: 1.65, w: 3.9, h: 1.05, fill: { color: \"FEF2F2\" } });\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: 1.65, w: 0.06, h: 1.05, fill: { color: C.red } });\n  s.addText(\"DeepSeek-R1\", {\n    x: 5.65, y: 1.7, w: 3.4, h: 0.25,\n    fontSize: 11, fontFace: FONT_B, color: C.red, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Reflects that drawer is open and tries to close it first — action fails. Gets stuck in loop.\", {\n    x: 5.65, y: 1.97, w: 3.4, h: 0.65,\n    fontSize: 10, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: 2.95, w: 3.9, h: 1.05, fill: { color: \"F0FDF4\" } });\n  s.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: 2.95, w: 0.06, h: 1.05, fill: { color: C.green } });\n  s.addText(\"KnowSelf (Llama-8B)\", {\n    x: 5.65, y: 3.0, w: 3.4, h: 0.25,\n    fontSize: 11, fontFace: FONT_B, color: C.green, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"Applies Knowledge token: place the object without removing unrelated items. Succeeds.\", {\n    x: 5.65, y: 3.27, w: 3.4, h: 0.65,\n    fontSize: 10, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  s.addText(\"KnowSelf selects the right cognitive mode — reflection where reflection helps, knowledge where knowledge is needed\", {\n    x: 0.6, y: 4.7, w: 8.8, h: 0.35,\n    fontSize: 11, fontFace: FONT_B, color: C.midGray, italic: true, align: \"left\", margin: 0,\n  });\n}\n\n// ========== SLIDE 6: ALFWORLD RESULTS TABLE ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"ALFWorld Results: 84.33% with Only 15% Knowledge\", {\n    x: 0.5, y: 0.2, w: 9.0, h: 0.5,\n    fontSize: 22, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n\n  const hdrOpts = { fill: { color: C.navy }, color: C.white, bold: true, fontSize: 8, fontFace: FONT_B, align: \"center\", valign: \"middle\" };\n  const cellOpts = { fontSize: 8, fontFace: FONT_B, color: C.bodyText, align: \"center\", valign: \"middle\" };\n  const hlOpts = { fontSize: 8, fontFace: FONT_B, color: C.darkText, bold: true, align: \"center\", valign: \"middle\", fill: { color: \"DBEAFE\" } };\n\n  const headers = [\"Backbone\", \"Method\", \"Know%\", \"Put\", \"Clean\", \"Heat\", \"Cool\", \"Examine\", \"Put Two\", \"All\"].map(h => ({\n    text: h, options: { ...hdrOpts },\n  }));\n\n  const rows = [\n    [\"GPT-4o\", \"ReAct\", \"0%\", \"83.33\", \"74.19\", \"69.57\", \"85.71\", \"77.78\", \"64.71\", \"76.12\"],\n    [\"GPT-4o\", \"Reflexion\", \"0%\", \"100.0\", \"87.10\", \"73.91\", \"90.48\", \"83.33\", \"70.59\", \"85.07\"],\n    [\"GPT-4o\", \"ExpeL\", \"100%\", \"95.83\", \"83.87\", \"69.57\", \"80.95\", \"88.89\", \"52.94\", \"79.85\"],\n    [\"Llama-8B\", \"ReAct\", \"0%\", \"33.33\", \"3.23\", \"0.00\", \"57.14\", \"66.67\", \"23.53\", \"27.61\"],\n    [\"Llama-8B\", \"Reflexion\", \"0%\", \"62.96\", \"22.73\", \"5.88\", \"64.29\", \"86.36\", \"50.00\", \"51.49\"],\n    [\"Llama-8B\", \"ExpeL\", \"100%\", \"83.33\", \"32.26\", \"30.43\", \"23.81\", \"55.56\", \"17.65\", \"41.04\"],\n    [\"Llama-8B\", \"ETO\", \"0%\", \"91.67\", \"70.59\", \"82.61\", \"61.90\", \"88.89\", \"64.71\", \"78.36\"],\n    [\"Llama-8B\", \"KnowAgent\", \"100%\", \"87.50\", \"93.55\", \"65.22\", \"66.67\", \"61.11\", \"64.71\", \"75.37\"],\n    [\"Llama-8B\", \"WKM\", \"100%\", \"95.83\", \"87.10\", \"86.96\", \"61.90\", \"66.67\", \"52.94\", \"77.61\"],\n    [\"Llama-8B\", \"KnowSelf\", \"15%\", \"91.67\", \"87.10\", \"91.30\", \"85.71\", \"77.78\", \"64.71\", \"84.33\"],\n    [\"Gemma-2B\", \"ReAct\", \"0%\", \"0.00\", \"9.68\", \"0.00\", \"4.76\", \"44.44\", \"0.00\", \"8.96\"],\n    [\"Gemma-2B\", \"ETO\", \"0%\", \"91.67\", \"83.87\", \"78.26\", \"52.38\", \"77.78\", \"29.41\", \"71.64\"],\n    [\"Gemma-2B\", \"KnowAgent\", \"100%\", \"91.67\", \"90.32\", \"69.57\", \"71.43\", \"66.67\", \"41.18\", \"73.88\"],\n    [\"Gemma-2B\", \"WKM\", \"100%\", \"91.67\", \"87.10\", \"78.26\", \"71.43\", \"61.11\", \"52.94\", \"76.12\"],\n    [\"Gemma-2B\", \"KnowSelf\", \"26%\", \"87.50\", \"93.55\", \"73.91\", \"76.19\", \"83.33\", \"52.94\", \"79.85\"],\n  ];\n\n  const highlightRows = [9, 14];\n  const tableData = [headers];\n  rows.forEach((row, ri) => {\n    const isHL = highlightRows.includes(ri);\n    tableData.push(row.map(cell => ({\n      text: cell,\n      options: isHL ? { ...hlOpts } : { ...cellOpts, fill: { color: ri % 2 === 0 ? C.white : C.cardBg } },\n    })));\n  });\n\n  s.addTable(tableData, {\n    x: 0.5, y: 0.8, w: 9.0,\n    colW: [0.82, 0.88, 0.6, 0.75, 0.75, 0.75, 0.75, 0.82, 0.82, 0.65],\n    border: { pt: 0.5, color: C.lightGray },\n    rowH: [0.26, ...Array(15).fill(0.26)],\n    margin: [1, 2, 1, 2],\n  });\n\n  s.addText(\"Success rates (%) on six ALFWorld task types. Highlighted rows: KnowSelf.\", {\n    x: 0.5, y: 5.0, w: 9.0, h: 0.3,\n    fontSize: 10, fontFace: FONT_B, color: C.midGray, italic: true, align: \"left\", margin: 0,\n  });\n}\n\n// ========== SLIDE 7: EFFICIENCY CHART ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.offWhite };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"Minimal Knowledge, Maximum Impact\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.5,\n    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText(\"KnowSelf uses 15–26% knowledge queries vs. 100% for competing methods, yet achieves best scores\", {\n    x: 0.6, y: 0.8, w: 8.8, h: 0.35,\n    fontSize: 13, fontFace: FONT_B, color: C.bodyText, align: \"left\", margin: 0,\n  });\n\n  const labels = [\"ExpeL\\n(GPT-4o)\", \"KnowAgent\\n(Llama-8B)\", \"WKM\\n(Llama-8B)\", \"KnowSelf\\n(Llama-8B)\", \"KnowAgent\\n(Gemma-2B)\", \"WKM\\n(Gemma-2B)\", \"KnowSelf\\n(Gemma-2B)\"];\n  const accuracyVals = [79.85, 75.37, 77.61, 84.33, 73.88, 76.12, 79.85];\n  const knowPctVals = [100, 100, 100, 15.01, 100, 100, 26.41];\n\n  s.addChart(pres.charts.BAR, [\n    { name: \"Overall Accuracy (%)\", labels, values: accuracyVals },\n    { name: \"Knowledge Usage (%)\", labels, values: knowPctVals },\n  ], {\n    x: 0.5, y: 1.25, w: 9.0, h: 3.2,\n    barDir: \"col\",\n    barGrouping: \"clustered\",\n    chartColors: [C.teal, C.accent],\n    chartArea: { fill: { color: C.white }, roundedCorners: true },\n    catAxisLabelColor: C.bodyText,\n    catAxisLabelFontSize: 8,\n    valAxisLabelColor: C.midGray,\n    valGridLine: { color: C.lightGray, size: 0.5 },\n    catGridLine: { style: \"none\" },\n    showValue: true,\n    dataLabelPosition: \"outEnd\",\n    dataLabelColor: C.darkText,\n    dataLabelFontSize: 7,\n    showLegend: true,\n    legendPos: \"b\",\n    legendFontSize: 9,\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.7, w: 9.0, h: 0.42, fill: { color: C.navy } });\n  s.addText(\"KnowSelf (Llama-8B): 84.33% accuracy with only 15% knowledge — surpasses GPT-4o ExpeL (79.85%) at 100% knowledge\", {\n    x: 0.7, y: 4.7, w: 8.6, h: 0.42,\n    fontSize: 11, fontFace: FONT_B, color: C.white, bold: true, align: \"center\", valign: \"middle\", margin: 0,\n  });\n}\n\n// ========== SLIDE 8: KEY TAKEAWAYS ==========\n{\n  const s = pres.addSlide();\n  s.background = { color: C.darkBg };\n  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });\n  s.addText(\"Key Takeaways & Future Directions\", {\n    x: 0.6, y: 0.25, w: 8.8, h: 0.55,\n    fontSize: 30, fontFace: FONT_H, color: C.white, bold: true, align: \"left\", margin: 0,\n  });\n\n  const takeaways = [\n    { num: \"1\", text: \"Indiscriminate knowledge injection is wasteful — selective use consistently outperforms blanket application\" },\n    { num: \"2\", text: \"Agents can learn situational self-awareness via special tokens with lightweight heuristic labeling\" },\n    { num: \"3\", text: \"KnowSelf (Llama-8B) achieves 84.33%, surpassing GPT-4o ReAct (76.12%) and ExpeL (79.85%)\" },\n    { num: \"4\", text: \"Only 15–26% knowledge usage needed versus 100% for KnowAgent, WKM, and ExpeL\" },\n    { num: \"5\", text: \"Scales across model sizes — even Gemma-2B reaches 79.85%, matching GPT-4o ExpeL\" },\n  ];\n\n  takeaways.forEach((t, i) => {\n    const yBase = 1.05 + i * 0.65;\n    s.addText(t.num, {\n      x: 0.6, y: yBase, w: 0.42, h: 0.42,\n      fontSize: 14, fontFace: FONT_B, color: C.darkBg, bold: true, align: \"center\", valign: \"middle\",\n      shape: pres.shapes.OVAL, fill: { color: C.tealLight },\n    });\n    s.addText(t.text, {\n      x: 1.2, y: yBase, w: 8.2, h: 0.5,\n      fontSize: 12.5, fontFace: FONT_B, color: C.lightGray, align: \"left\", valign: \"middle\", margin: 0,\n    });\n  });\n\n  s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.35, w: 8.8, h: 0.05, fill: { color: C.teal, transparency: 50 } });\n  s.addText(\"Future Directions\", {\n    x: 0.6, y: 4.5, w: 8.8, h: 0.35,\n    fontSize: 15, fontFace: FONT_H, color: C.tealLight, bold: true, align: \"left\", margin: 0,\n  });\n  s.addText([\n    { text: \"Extend to multi-modal agents and real-world robotics\", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: FONT_B, color: C.midGray } },\n    { text: \"Explore dynamic knowledge base construction\", options: { bullet: true, breakLine: true, fontSize: 11, fontFace: FONT_B, color: C.midGray } },\n    { text: \"Apply self-awareness paradigm to multi-agent collaboration\", options: { bullet: true, fontSize: 11, fontFace: FONT_B, color: C.midGray } },\n  ], { x: 0.6, y: 4.85, w: 8.8, h: 0.6, margin: 0 });\n}\n\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" }).then(() => {\n  console.log(\"Saved to /app/output/final_deck.pptx\");\n}).catch(err => console.error(\"Error:\", err));\n", "numLines": 489, "startLine": 1, "totalLines": 489}}

