const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "KnowSelf Research";
pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";

const C = {
  darkBg: "0F1B2D",
  navy: "1A2744",
  teal: "0891B2",
  tealLight: "22D3EE",
  white: "FFFFFF",
  offWhite: "F0F4F8",
  lightGray: "E2E8F0",
  midGray: "64748B",
  darkText: "1E293B",
  bodyText: "334155",
  accent: "F59E0B",
  green: "10B981",
  red: "EF4444",
  cardBg: "F8FAFC",
};

const FONT_H = "Georgia";
const FONT_B = "Calibri";
const cardShadow = () => ({ type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.10 });

// ========== SLIDE 1: TITLE ==========
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("KnowSelf", {
    x: 0.8, y: 1.2, w: 8.0, h: 0.9,
    fontSize: 48, fontFace: FONT_H, color: C.tealLight, bold: true, align: "left", margin: 0,
  });
  s.addText("Agentic Knowledgeable Self-Awareness\nfor LLM-Based Agents", {
    x: 0.8, y: 2.1, w: 8.0, h: 1.0,
    fontSize: 22, fontFace: FONT_H, color: C.white, align: "left", margin: 0,
  });
  s.addText("Teaching agents to autonomously decide when to act, reflect, or seek knowledge", {
    x: 0.8, y: 3.3, w: 8.0, h: 0.5,
    fontSize: 14, fontFace: FONT_B, color: C.lightGray, italic: true, align: "left", margin: 0,
  });
  s.addText("arxiv.org/abs/2504.03553", {
    x: 0.8, y: 4.2, w: 4, h: 0.4,
    fontSize: 12, fontFace: FONT_B, color: C.teal, align: "left", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: 8.8, y: 1.2, w: 0.08, h: 2.5, fill: { color: C.teal, transparency: 40 } });
}

// ========== SLIDE 2: PROBLEM ==========
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("The Problem: Indiscriminate \"Flood Irrigation\"", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.55,
    fontSize: 26, fontFace: FONT_H, color: C.darkText, bold: true, align: "left", margin: 0,
  });

  const paradigms = [
    { title: "Trajectory Imitation", desc: "ReAct: blindly imitates gold trajectories without understanding when help is needed", icon: "1" },
    { title: "Trial-and-Error", desc: "Reflexion: always reflects even when the agent already knows the correct action", icon: "2" },
    { title: "Knowledge-Augmented", desc: "KnowAgent, WKM: injects domain knowledge at every step — 100% usage regardless of need", icon: "3" },
  ];

  paradigms.forEach((p, i) => {
    const yBase = 1.1 + i * 1.05;
    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yBase, w: 5.2, h: 0.85, fill: { color: C.white }, shadow: cardShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yBase, w: 0.07, h: 0.85, fill: { color: C.red } });
    s.addText(p.icon, {
      x: 0.85, y: yBase + 0.08, w: 0.35, h: 0.35,
      fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle",
      shape: pres.shapes.OVAL, fill: { color: C.red },
    });
    s.addText(p.title, {
      x: 1.35, y: yBase + 0.06, w: 4.3, h: 0.3,
      fontSize: 13, fontFace: FONT_B, color: C.darkText, bold: true, align: "left", margin: 0,
    });
    s.addText(p.desc, {
      x: 1.35, y: yBase + 0.38, w: 4.3, h: 0.4,
      fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
    });
  });

  // Right callout — within margin
  s.addShape(pres.shapes.RECTANGLE, { x: 6.1, y: 1.1, w: 3.3, h: 3.15, fill: { color: C.navy }, shadow: cardShadow() });
  s.addText("Human Approach", {
    x: 6.3, y: 1.3, w: 2.9, h: 0.35,
    fontSize: 15, fontFace: FONT_H, color: C.tealLight, bold: true, align: "left", margin: 0,
  });
  s.addText("Humans possess situational self-awareness: the metacognitive ability to assess whether they can handle a situation directly, need to pause and reflect, or must seek external help.", {
    x: 6.3, y: 1.75, w: 2.9, h: 1.3,
    fontSize: 11, fontFace: FONT_B, color: C.lightGray, align: "left", margin: 0,
  });
  s.addText("KnowSelf brings this\ncapability to LLM agents.", {
    x: 6.3, y: 3.2, w: 2.9, h: 0.7,
    fontSize: 13, fontFace: FONT_B, color: C.accent, bold: true, align: "left", margin: 0,
  });

  s.addText("Result: fragile planning, pattern collapse, and unnecessarily high inference costs", {
    x: 0.6, y: 4.65, w: 8.8, h: 0.35,
    fontSize: 11, fontFace: FONT_B, color: C.midGray, italic: true, align: "left", margin: 0,
  });
}

// ========== SLIDE 3: THREE THINKING MODES ==========
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("Three Situational Thinking Modes", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.55,
    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: "left", margin: 0,
  });

  // Node 1
  const dY = 1.1;
  s.addShape(pres.shapes.RECTANGLE, { x: 3.2, y: dY, w: 3.6, h: 0.55, fill: { color: C.navy }, shadow: cardShadow() });
  s.addText("Agent Predicts Action at Step t", {
    x: 3.2, y: dY, w: 3.6, h: 0.55,
    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });

  // Arrow down
  s.addShape(pres.shapes.LINE, { x: 5.0, y: dY + 0.55, w: 0, h: 0.25, line: { color: C.midGray, width: 1.5 } });

  // Decision node
  const d2Y = 1.9;
  s.addShape(pres.shapes.RECTANGLE, { x: 3.2, y: d2Y, w: 3.6, h: 0.5, fill: { color: C.teal } });
  s.addText("Does predicted action match gold action?", {
    x: 3.2, y: d2Y, w: 3.6, h: 0.5,
    fontSize: 11, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });

  // YES branch left → Fast Thinking
  s.addShape(pres.shapes.LINE, { x: 2.0, y: d2Y + 0.25, w: 1.2, h: 0, line: { color: C.green, width: 1.5 } });
  s.addText("YES", {
    x: 2.2, y: d2Y - 0.18, w: 0.6, h: 0.25,
    fontSize: 9, fontFace: FONT_B, color: C.green, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 2.0, y: d2Y + 0.25, w: 0, h: 0.55, line: { color: C.green, width: 1.5 } });

  const fastY = 2.7;
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: fastY, w: 2.8, h: 1.7, fill: { color: C.white }, shadow: cardShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: fastY, w: 2.8, h: 0.4, fill: { color: C.green } });
  s.addText("Fast Thinking", {
    x: 0.5, y: fastY, w: 2.8, h: 0.4,
    fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });
  s.addText("Agent directly produces the correct action with minimal deliberation.\n\nNo reflection or knowledge needed.", {
    x: 0.7, y: fastY + 0.5, w: 2.4, h: 1.1,
    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });

  // NO branch right → Reflection check
  s.addShape(pres.shapes.LINE, { x: 6.8, y: d2Y + 0.25, w: 0.7, h: 0, line: { color: C.red, width: 1.5 } });
  s.addText("NO", {
    x: 7.0, y: d2Y - 0.18, w: 0.5, h: 0.25,
    fontSize: 9, fontFace: FONT_B, color: C.red, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 7.5, y: d2Y + 0.25, w: 0, h: 0.35, line: { color: C.red, width: 1.5 } });

  // Reflection check
  const r2Y = 2.6;
  s.addShape(pres.shapes.RECTANGLE, { x: 5.9, y: r2Y, w: 3.2, h: 0.45, fill: { color: C.accent } });
  s.addText("Can reflection fix it?", {
    x: 5.9, y: r2Y, w: 3.2, h: 0.45,
    fontSize: 11, fontFace: FONT_B, color: C.darkText, bold: true, align: "center", valign: "middle", margin: 0,
  });

  // YES → Slow Thinking
  s.addShape(pres.shapes.LINE, { x: 5.9, y: r2Y + 0.22, w: 0, h: 0, line: { color: C.accent, width: 1.5 } });
  s.addText("YES", {
    x: 4.6, y: r2Y + 0.02, w: 0.5, h: 0.25,
    fontSize: 9, fontFace: FONT_B, color: C.accent, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 5.15, y: r2Y + 0.45, w: 0, h: 0.45, line: { color: C.accent, width: 1.5 } });

  const slowY = 3.5;
  s.addShape(pres.shapes.RECTANGLE, { x: 3.65, y: slowY, w: 2.8, h: 1.1, fill: { color: C.white }, shadow: cardShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 3.65, y: slowY, w: 2.8, h: 0.38, fill: { color: C.accent } });
  s.addText("Slow Thinking", {
    x: 3.65, y: slowY, w: 2.8, h: 0.38,
    fontSize: 12, fontFace: FONT_B, color: C.darkText, bold: true, align: "center", valign: "middle", margin: 0,
  });
  s.addText("Agent self-corrects through reflection after initial error.", {
    x: 3.85, y: slowY + 0.45, w: 2.4, h: 0.55,
    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });

  // NO → Knowledgeable Thinking
  s.addText("NO", {
    x: 9.0, y: r2Y + 0.02, w: 0.5, h: 0.25,
    fontSize: 9, fontFace: FONT_B, color: C.red, bold: true, align: "center", margin: 0,
  });
  s.addShape(pres.shapes.LINE, { x: 8.25, y: r2Y + 0.45, w: 0, h: 0.6, line: { color: C.red, width: 1.5 } });

  const knowY = 3.5;
  s.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: knowY, w: 2.8, h: 1.1, fill: { color: C.white }, shadow: cardShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: knowY, w: 2.8, h: 0.38, fill: { color: C.teal } });
  s.addText("Knowledgeable Thinking", {
    x: 6.7, y: knowY, w: 2.8, h: 0.38,
    fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });
  s.addText("Agent must consult external knowledge base.", {
    x: 6.9, y: knowY + 0.45, w: 2.4, h: 0.55,
    fontSize: 10.5, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });
}

// ========== SLIDE 4: FRAMEWORK PIPELINE ==========
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("KnowSelf Framework Pipeline", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.55,
    fontSize: 28, fontFace: FONT_H, color: C.darkText, bold: true, align: "left", margin: 0,
  });

  const steps = [
    { num: "1", title: "Data Construction", lines: ["Agent self-explores environments", "Heuristic criterion classifies each step", "Special tokens inserted for situation type"] },
    { num: "2", title: "Two-Stage Training", lines: ["Stage A: Supervised Fine-Tuning (SFT)", "Stage B: Reward-based Policy Optimization (RPO)", "Refines special token generation"] },
    { num: "3", title: "Self-Aware Inference", lines: ["Agent generates special tokens at each step", "Tokens trigger: action / reflection / retrieval", "Knowledge retrieved only when needed"] },
  ];

  steps.forEach((st, i) => {
    const xBase = 0.6 + i * 3.05;
    s.addShape(pres.shapes.RECTANGLE, { x: xBase, y: 1.1, w: 2.8, h: 3.2, fill: { color: C.white }, shadow: cardShadow() });
    s.addText(st.num, {
      x: xBase + 1.0, y: 1.3, w: 0.6, h: 0.6,
      fontSize: 20, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle",
      shape: pres.shapes.OVAL, fill: { color: C.teal },
    });
    s.addText(st.title, {
      x: xBase + 0.2, y: 2.05, w: 2.4, h: 0.4,
      fontSize: 14, fontFace: FONT_B, color: C.darkText, bold: true, align: "center", margin: 0,
    });
    const bulletItems = st.lines.map((l, li) => ({
      text: l,
      options: { bullet: true, breakLine: li < st.lines.length - 1, fontSize: 11, fontFace: FONT_B, color: C.bodyText },
    }));
    s.addText(bulletItems, { x: xBase + 0.25, y: 2.55, w: 2.3, h: 1.5, margin: 0, paraSpaceAfter: 6 });

    if (i < 2) {
      s.addShape(pres.shapes.LINE, { x: xBase + 2.8, y: 2.7, w: 0.25, h: 0, line: { color: C.teal, width: 2 } });
    }
  });

  s.addText("Lightweight and data-efficient: heuristic labeling on self-explored trajectories — no expensive human annotation", {
    x: 0.6, y: 4.6, w: 8.8, h: 0.35,
    fontSize: 11, fontFace: FONT_B, color: C.midGray, italic: true, align: "left", margin: 0,
  });
}

// ========== SLIDE 5: QUALITATIVE EXAMPLES ==========
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  s.addText("KnowSelf vs. Strong Baselines: Qualitative Examples", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.5,
    fontSize: 26, fontFace: FONT_H, color: C.darkText, bold: true, align: "left", margin: 0,
  });

  // Example A
  s.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.05, w: 4.3, h: 3.4, fill: { color: C.white }, shadow: cardShadow() });
